 protected function setUp():void {parent::setUp();$this->dir=sys_get_temp_dir().'/ccs-ui70-'.bin2hex(random_bytes(4));foreach(['bootstrap/cache','config','routes','storage/framework/views'] as $d)mkdir($this->dir.'/'.$d,0700,true);file_put_contents($this->dir.'/bootstrap/providers.php','<?php return [];');$this->app=Application::configure(basePath:$this->dir)->withRouting(using:static function(){})->withExceptions(static function(){})->withMiddleware(static function(){})->create();$this->app->make(\Illuminate\Contracts\Console\Kernel::class)->bootstrap();config(['database.default'=>'sqlite','database.connections.sqlite'=>['driver'=>'sqlite','database'=>':memory:','prefix'=>''],'app.key'=>'base64:'.base64_encode(str_repeat('p',32)),'app.cipher'=>'AES-256-CBC','ccs_admin.locales'=>['en'=>'English','si'=>'සිංහල'],'session.driver'=>'array']);$this->session=new \Illuminate\Session\Store('ui70',new \Illuminate\Session\ArraySessionHandler(120));$this->session->start();$this->app->instance('session',$this->session);$this->app->instance('session.store',$this->session);
 Schema::create('repair_jobs',function(Blueprint $t){$t->id();$t->string('status');$t->integer('vehicle_id')->nullable();$t->string('job_number')->nullable();$t->string('service_type')->nullable();$t->timestamp('created_at')->nullable();$t->softDeletes();});Schema::create('customers',function(Blueprint $t){$t->id();$t->string('name');$t->string('customer_code');$t->string('phone');$t->softDeletes();});Schema::create('vehicles',function(Blueprint $t){$t->id();$t->integer('customer_id');$t->string('registration_number');$t->string('make');$t->string('model');$t->softDeletes();});Schema::create('invoices',function(Blueprint $t){$t->id();$t->integer('repair_job_id');$t->string('status');});Schema::create('payments',function(Blueprint $t){$t->id();$t->integer('invoice_id');$t->string('request_token');});Schema::create('ccs_staff_preferences',function(Blueprint $t){$t->id();$t->integer('user_id');$t->text('preferences');$t->timestamps();});Schema::create('audit_logs',function(Blueprint $t){$t->id();$t->integer('user_id');$t->string('action');$t->string('entity_type');$t->integer('entity_id')->nullable();$t->text('metadata')->nullable();$t->timestamps();});$this->app['router']->get('/settings',fn()=>null)->name('ccs.settings');$this->app['router']->getRoutes()->refreshNameLookups(); }
 protected function tearDown():void {\Illuminate\Foundation\Bootstrap\HandleExceptions::flushHandlersState($this);DB::disconnect();\Illuminate\Support\Facades\Facade::clearResolvedInstances();$it=new \RecursiveIteratorIterator(new \RecursiveDirectoryIterator($this->dir,\FilesystemIterator::SKIP_DOTS),\RecursiveIteratorIterator::CHILD_FIRST);foreach($it as $p){$p->isDir()?rmdir($p->getPathname()):unlink($p->getPathname());}rmdir($this->dir);parent::tearDown();}
 private function req(array $data):Request {$r=Request::create('/test','POST',$data,[],[],['HTTP_ACCEPT'=>'application/json']);$r->setLaravelSession($this->session);$this->app->instance('request',$r);$r->setUserResolver(fn()=>new \Illuminate\Auth\GenericUser(['id'=>1,'name'=>'TEST Owner','email'=>'test@example.invalid','ccs_role'=>'owner']));return $r;}
 public function test_only_ready_completed_are_billable():void {foreach(['ready','completed'] as $s){$id=DB::table('repair_jobs')->insertGetId(['status'=>$s]);(new CcsJobBillingGate)->check($id);self::assertTrue(CcsJobBillingGate::allowed($s));}foreach(['new_enquiry','vehicle_received','repair_in_progress','testing','awaiting_parts','awaiting_approval','delivered','closed','unknown'] as $s){self::assertFalse(CcsJobBillingGate::allowed($s));}}
 public function test_unfinished_job_create_is_rejected_without_invoice_or_payment():void {DB::table('repair_jobs')->insert(['id'=>1,'status'=>'repair_in_progress']);$r=$this->req(['repair_job_id'=>1,'description'=>['TEST service'],'quantity'=>[1],'unit_price'=>[10000],'initial_received'=>4000,'initial_request_token'=>'b317f1ba-ad96-4204-8db6-337ca4c1d013']);try{(new \App\Http\Controllers\CcsAdminController)->createInvoice($r);self::fail('Expected billing refusal');}catch(ValidationException $e){self::assertArrayHasKey('repair_job_id',$e->errors());}self::assertSame(0,DB::table('invoices')->count());self::assertSame(0,DB::table('payments')->count());}
 public function test_old_draft_cannot_finalize_after_job_status_changes():void {$id=DB::table('repair_jobs')->insertGetId(['status'=>'ready']);(new CcsJobBillingGate)->check($id);DB::table('repair_jobs')->where('id',$id)->update(['status'=>'testing']);DB::table('invoices')->insert(['id'=>1,'repair_job_id'=>$id,'status'=>'draft']);$r=$this->req(['confirmation'=>1,'method'=>'cash','amount_received'=>4000,'request_token'=>'b317f1ba-ad96-4204-8db6-337ca4c1d014']);try{(new \App\Http\Controllers\CcsBillingController)->issue($r,1);self::fail('Expected status refusal');}catch(ValidationException $e){self::assertArrayHasKey('repair_job_id',$e->errors());}self::assertSame('draft',DB::table('invoices')->value('status'));self::assertSame(0,DB::table('payments')->count());}
 public function test_deleted_job_is_not_billable():void {$id=DB::table('repair_jobs')->insertGetId(['status'=>'ready','deleted_at'=>now()]);$this->expectException(ValidationException::class);(new CcsJobBillingGate)->check($id);}
 public function test_top_language_json_saves_session_and_cookie():void {$r=$this->req(['language'=>'si']);$response=(new \App\Http\Controllers\CcsSettingsController)->language($r);self::assertSame('si',$this->session->get('ccs_language'));self::assertSame('si',$response->getData(true)['language']);self::assertSame('ccs_language',$response->headers->getCookies()[0]->getName());}
 public function test_default2_theme_saves_without_losing_other_preferences():void {DB::table('ccs_staff_preferences')->insert(['user_id'=>1,'preferences'=>json_encode(['input_method'=>'phonetic','invoice_locale'=>'si']),'created_at'=>now(),'updated_at'=>now()]);$r=$this->req(['theme'=>'default2']);(new \App\Http\Controllers\CcsSettingsController)->theme($r);$p=json_decode(DB::table('ccs_staff_preferences')->value('preferences'),true);self::assertSame('default2',$p['theme']);self::assertSame('phonetic',$p['input_method']);self::assertSame('si',$p['invoice_locale']);}
 public function test_pos_search_returns_ready_and_in_service_statuses():void {DB::table('customers')->insert(['id'=>1,'name'=>'TEST Kasun','customer_code'=>'TEST-C70','phone'=>'0000000000']);DB::table('vehicles')->insert(['id'=>1,'customer_id'=>1,'registration_number'=>'TEST-70','make'=>'Toyota','model'=>'Prius']);DB::table('repair_jobs')->insert([['id'=>1,'vehicle_id'=>1,'status'=>'ready','job_number'=>'TEST-J70-A'],['id'=>2,'vehicle_id'=>1,'status'=>'repair_in_progress','job_number'=>'TEST-J70-B']]);$r=$this->req(['q'=>'TEST-C70']);$res=(new \App\Http\Controllers\CcsAdminController)->posJobSearch($r);$rows=$res->getData(true)['data'];self::assertCount(2,$rows);self::assertSame(['repair_in_progress','ready'],array_column($rows,'status'));self::assertSame('no-store, private',$res->headers->get('Cache-Control'));}
 public function test_invalid_language_does_not_change_session():void {$this->session->put('ccs_language','en');try{(new \App\Http\Controllers\CcsSettingsController)->language($this->req(['language'=>'bad']));self::fail('Invalid language accepted');}catch(ValidationException $e){self::assertArrayHasKey('language',$e->errors());}self::assertSame('en',$this->session->get('ccs_language'));}

 public function test_custom_accent_saves_and_rejects_css_injection():void {(new \App\Http\Controllers\CcsSettingsController)->theme($this->req(['theme'=>'default2','custom_accent'=>1,'accent_color'=>'#FACD29','accent_brightness'=>75]));$p=json_decode(DB::table('ccs_staff_preferences')->value('preferences'),true);self::assertTrue($p['custom_accent']);self::assertSame('#FACD29',$p['accent_color']);self::assertSame('75',(string)$p['accent_brightness']);try{(new \App\Http\Controllers\CcsSettingsController)->theme($this->req(['theme'=>'default2','accent_color'=>'red;display:none']));self::fail('Bad colour accepted');}catch(ValidationException $e){self::assertArrayHasKey('accent_color',$e->errors());}}
