 $r=$this->req(['repair_job_id'=>1,'description'=>['TEST service'],'quantity'=>[1],'unit_price'=>[10000],'initial_received'=>10000,'initial_method'=>'card','initial_reference'=>'TEST-CARD-71','invoice_locale'=>'en','initial_request_token'=>'b317f1ba-ad96-4204-8db6-337ca4c1d071']);
 (new \App\Http\Controllers\CcsAdminController)->createInvoice($r);self::assertSame('draft',DB::table('invoices')->value('status'));self::assertSame(0,DB::table('payments')->count());self::assertSame(10000.0,(float)$this->session->get('ccs_pos_payment.1.amount'));self::assertSame('card',$this->session->get('ccs_pos_payment.1.method'));$final=$this->req(['confirmation'=>1,'amount_received'=>10000,'method'=>'card','reference'=>'TEST-CARD-71','request_token'=>'b317f1ba-ad96-4204-8db6-337ca4c1d072']);(new \App\Http\Controllers\CcsBillingController)->issue($final,1);self::assertNull($this->session->get('ccs_pos_payment.1'));$payment=DB::table('payments')->first();self::assertSame('card',$payment->method);self::assertSame('TEST-CARD-71',$payment->reference);self::assertSame(10000.0,(float)$payment->amount_lkr);self::assertSame('paid',DB::table('invoices')->value('status'));
